import React, { useLayoutEffect, useMemo, useRef } from "react";
import { gsap } from "gsap";
import "./homeLoader.css";

/*
  Exact sound from the reference clip is embedded directly in this component.
  No /public audio file and no external sound URL are required.
*/
const INTRO_AUDIO =
  "data:audio/mpeg;base64,";

function HomeLoader({ onFinish }) {
  const rootRef = useRef(null);
  const audioRef = useRef(null);
  const finishedRef = useRef(false);
  const introStartedAtRef = useRef(0);
  const unlockAttachedRef = useRef(false);

  const sparks = useMemo(
    () =>
      Array.from({ length: 56 }, (_, index) => ({
        id: index,
        left: `${8 + ((index * 41) % 84)}%`,
        top: `${7 + ((index * 67) % 82)}%`,
        size: `${1 + ((index * 11) % 4) * 0.45}px`,
        delay: `${((index * 7) % 18) * 0.08}s`,
      })),
    []
  );

  const embers = useMemo(
    () =>
      Array.from({ length: 58 }, (_, index) => ({
        id: index,
        x: `${-270 + ((index * 47) % 590)}px`,
        y: `${-40 - ((index * 29) % 220)}px`,
        delay: `${2.75 + ((index * 13) % 26) * 0.045}s`,
        duration: `${1.5 + ((index * 17) % 16) * 0.07}s`,
        size: `${1.2 + ((index * 9) % 5) * 0.55}px`,
      })),
    []
  );

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const audio = audioRef.current;
    introStartedAtRef.current = performance.now();

    const getElapsed = () =>
      Math.max(
        0,
        (performance.now() - introStartedAtRef.current) / 1000
      );

    const removeUnlockListeners = () => {
      if (!unlockAttachedRef.current) return;

      window.removeEventListener("pointerdown", unlockAudio, true);
      window.removeEventListener("touchstart", unlockAudio, true);
      window.removeEventListener("keydown", unlockAudio, true);

      unlockAttachedRef.current = false;
    };

    const playAudio = async (syncToAnimation = false) => {
      if (!audio) return false;

      try {
        audio.muted = false;
        audio.volume = 1;

        if (syncToAnimation) {
          const elapsed = getElapsed();

          if (
            Number.isFinite(audio.duration) &&
            audio.duration > 0
          ) {
            audio.currentTime = Math.min(
              elapsed,
              Math.max(0, audio.duration - 0.05)
            );
          } else if (audio.readyState >= 1) {
            audio.currentTime = elapsed;
          }
        } else {
          audio.currentTime = 0;
        }

        await audio.play();
        removeUnlockListeners();

        console.log("[FALDREN] Intro sound playing.");
        return true;
      } catch (error) {
        console.warn(
          "[FALDREN] Audible autoplay blocked by browser:",
          error
        );

        return false;
      }
    };

    function unlockAudio() {
      playAudio(true);
    }

    const attachUnlockListeners = () => {
      if (unlockAttachedRef.current) return;

      window.addEventListener("pointerdown", unlockAudio, true);
      window.addEventListener("touchstart", unlockAudio, true);
      window.addEventListener("keydown", unlockAudio, true);

      unlockAttachedRef.current = true;
    };

    // Try direct sound immediately.
    playAudio(false).then((played) => {
      if (!played) {
        // No extra ENTER screen.
        // First natural click/tap/key anywhere unlocks the same sound.
        attachUnlockListeners();
      }
    });

    const ctx = gsap.context(() => {
      gsap.set(".rx-logo", {
        opacity: 0,
        scale: 0.94,
      });

      gsap.set(".rx-logo-metal", {
        opacity: 0,
      });

      gsap.set(".rx-logo-outline", {
        opacity: 0,
      });

      gsap.set(".rx-trail", {
        strokeDashoffset: 1100,
        opacity: 0,
      });

      gsap.set(".rx-smoke-ring", {
        opacity: 0,
        scale: 0.28,
      });

      gsap.set(".rx-smoke-ring-outer", {
        opacity: 0,
        scale: 0.2,
      });

      gsap.set(".rx-horizontal-flare", {
        opacity: 0,
        scaleX: 0.06,
      });

      gsap.set(".rx-floor-light", {
        opacity: 0,
        scaleX: 0.15,
      });

      gsap.set(".rx-word span", {
        opacity: 0,
        y: 16,
        filter: "blur(8px)",
      });

      gsap.set(".rx-final-stars", {
        opacity: 0,
      });

      gsap.set(".rx-ember", {
        opacity: 0,
        x: 0,
        y: 0,
        scale: 0.35,
      });

      const finishIntro = () => {
        if (finishedRef.current) return;

        finishedRef.current = true;

        if (audio) {
          gsap.to(audio, {
            volume: 0,
            duration: 0.22,
            ease: "power2.out",
            onComplete: () => {
              try {
                audio.pause();
                audio.currentTime = 0;
              } catch {
                // no-op
              }
            },
          });
        }

        gsap.to(root, {
          opacity: 0,
          duration: 0.28,
          ease: "power2.inOut",
          onComplete: () => {
            onFinish?.();
          },
        });
      };

      const tl = gsap.timeline({
        defaults: {
          ease: "power3.out",
        },
      });

      /* =====================================================
         0.00 - 1.65s
         GOLD LIGHT LINES DRAW / ORBIT AROUND THE F
      ===================================================== */

      tl.to(
        ".rx-trail",
        {
          opacity: 1,
          strokeDashoffset: 0,
          duration: 1.3,
          stagger: 0.055,
          ease: "power2.inOut",
        },
        0.12
      );

      tl.to(
        ".rx-logo-outline",
        {
          opacity: 0.34,
          duration: 0.45,
        },
        0.58
      );

      tl.fromTo(
        ".rx-line-particles",
        {
          opacity: 0,
          scale: 0.75,
        },
        {
          opacity: 0.95,
          scale: 1,
          duration: 0.5,
          ease: "power2.out",
        },
        0.72
      );

      /* =====================================================
         1.35 - 2.05s
         SILVER F RESOLVES UNDER THE GOLD LINES
      ===================================================== */

      tl.to(
        ".rx-logo",
        {
          opacity: 1,
          scale: 1,
          duration: 0.65,
          ease: "back.out(1.55)",
        },
        1.3
      );

      tl.to(
        ".rx-logo-metal",
        {
          opacity: 1,
          duration: 0.55,
          ease: "power3.out",
        },
        1.38
      );

      tl.to(
        ".rx-trail",
        {
          opacity: 0.35,
          duration: 0.45,
        },
        1.55
      );

      /* =====================================================
         1.80 - 2.85s
         SMOKE SHOCKWAVE EXACTLY LIKE THE REFERENCE PHASE
      ===================================================== */

      tl.to(
        ".rx-smoke-ring",
        {
          opacity: 0.92,
          scale: 1,
          duration: 0.34,
          ease: "power4.out",
        },
        1.78
      );

      tl.to(
        ".rx-smoke-ring-outer",
        {
          opacity: 0.68,
          scale: 1,
          duration: 0.38,
          ease: "power4.out",
        },
        1.86
      );

      tl.to(
        ".rx-smoke-ring",
        {
          opacity: 0.06,
          scale: 1.55,
          rotate: 10,
          duration: 1.0,
          ease: "power2.out",
        },
        2.03
      );

      tl.to(
        ".rx-smoke-ring-outer",
        {
          opacity: 0.03,
          scale: 1.82,
          rotate: -13,
          duration: 1.1,
          ease: "power2.out",
        },
        2.12
      );

      tl.to(
        ".rx-trail",
        {
          opacity: 0,
          duration: 0.5,
        },
        1.95
      );

      /* =====================================================
         2.70 - 6.0s
         EMBERS + SMALL ORANGE PARTICLES
      ===================================================== */

      tl.to(
        ".rx-ember",
        {
          opacity: (index) =>
            0.3 + ((index * 7) % 7) * 0.1,

          x: (index) =>
            -260 + ((index * 47) % 580),

          y: (index) =>
            -40 - ((index * 29) % 220),

          scale: (index) =>
            0.65 + ((index * 11) % 8) * 0.08,

          duration: (index) =>
            1.25 + ((index * 17) % 14) * 0.08,

          stagger: 0.014,

          ease: "power2.out",
        },
        2.72
      );

      tl.to(
        ".rx-ember",
        {
          opacity: 0,
          duration: 0.52,
          stagger: 0.008,
        },
        5.55
      );

      /* =====================================================
         3.20 - 4.20s
         COOL HORIZONTAL LENS FLARE THROUGH THE F
      ===================================================== */

      tl.to(
        ".rx-horizontal-flare",
        {
          opacity: 0.9,
          scaleX: 1,
          duration: 0.24,
          ease: "power4.out",
        },
        3.17
      );

      tl.to(
        ".rx-horizontal-flare",
        {
          opacity: 0.13,
          scaleX: 0.8,
          duration: 0.78,
          ease: "power2.out",
        },
        3.41
      );

      tl.to(
        ".rx-horizontal-flare",
        {
          opacity: 0,
          duration: 0.52,
        },
        4.15
      );

      /* =====================================================
         4.65 - 6.10s
         FALDREN REVEAL + WARM FLOOR LIGHT
      ===================================================== */

      tl.to(
        ".rx-floor-light",
        {
          opacity: 1,
          scaleX: 1,
          duration: 0.34,
          ease: "power4.out",
        },
        4.67
      );

      tl.to(
        ".rx-word span",
        {
          opacity: 1,
          y: 0,
          filter: "blur(0px)",
          duration: 0.34,
          stagger: 0.06,
          ease: "power4.out",
        },
        4.72
      );

      // FALDREN complete-a visible aana udane Home page.
      tl.call(
        finishIntro,
        [],
        5.48
      );

      // No long final hold: Home opens as soon as FALDREN completes.

    }, root);

    return () => {
      removeUnlockListeners();

      if (audio) {
        try {
          audio.pause();
          audio.currentTime = 0;
          audio.volume = 1;
        } catch {
          // no-op
        }
      }

      ctx.revert();
      document.body.style.overflow = previousOverflow;
    };
  }, [onFinish]);

  return (
    <div
      ref={rootRef}
      className="rx-loader is-running"
    >
      <audio
        ref={audioRef}
        src={INTRO_AUDIO}
        preload="auto"
        autoPlay
        playsInline
      />


      <div className="rx-final-stars" />

      <div className="rx-static-stars">
        {sparks.map((spark) => (
          <span
            key={spark.id}
            className="rx-static-star"
            style={{
              left: spark.left,
              top: spark.top,
              width: spark.size,
              height: spark.size,
              animationDelay: spark.delay,
            }}
          />
        ))}
      </div>

      <div className="rx-stage">
        <div className="rx-smoke-ring" />
        <div className="rx-smoke-ring rx-smoke-ring-outer" />
        <div className="rx-horizontal-flare" />

        <div className="rx-line-particles">
          {Array.from({ length: 20 }).map((_, index) => (
            <span
              key={index}
              style={{
                "--a": `${index * 37}deg`,
                "--d": `${86 + ((index * 31) % 95)}px`,
              }}
            />
          ))}
        </div>

        <div className="rx-embers">
          {embers.map((ember) => (
            <span
              key={ember.id}
              className="rx-ember"
              style={{
                width: ember.size,
                height: `calc(${ember.size} * 4)`,
              }}
            />
          ))}
        </div>

        <div className="rx-logo-wrap">
          <svg
            className="rx-logo"
            viewBox="0 0 340 340"
            role="presentation"
          >
            <defs>
              <linearGradient
                id="rxSilverFront"
                x1="0%"
                y1="0%"
                x2="100%"
                y2="100%"
              >
                <stop offset="0%" stopColor="#ffffff" />
                <stop offset="15%" stopColor="#dadada" />
                <stop offset="34%" stopColor="#ffffff" />
                <stop offset="50%" stopColor="#9b9b9b" />
                <stop offset="69%" stopColor="#ececec" />
                <stop offset="100%" stopColor="#4a4a4a" />
              </linearGradient>

              <linearGradient
                id="rxSilverSide"
                x1="0%"
                y1="0%"
                x2="100%"
                y2="100%"
              >
                <stop offset="0%" stopColor="#6e6e6e" />
                <stop offset="100%" stopColor="#171717" />
              </linearGradient>

              <linearGradient
                id="rxSilverDark"
                x1="0%"
                y1="0%"
                x2="100%"
                y2="0%"
              >
                <stop offset="0%" stopColor="#262626" />
                <stop offset="52%" stopColor="#676767" />
                <stop offset="100%" stopColor="#1b1b1b" />
              </linearGradient>

              <linearGradient
                id="rxGold"
                x1="0%"
                y1="0%"
                x2="100%"
                y2="100%"
              >
                <stop offset="0%" stopColor="#8a5d25" />
                <stop offset="45%" stopColor="#fff0b2" />
                <stop offset="100%" stopColor="#9c692b" />
              </linearGradient>

              <filter
                id="rxGoldGlow"
                x="-120%"
                y="-120%"
                width="340%"
                height="340%"
              >
                <feGaussianBlur stdDeviation="4.4" result="blur" />
                <feMerge>
                  <feMergeNode in="blur" />
                  <feMergeNode in="SourceGraphic" />
                </feMerge>
              </filter>

              <filter
                id="rxMetalShadow"
                x="-100%"
                y="-100%"
                width="300%"
                height="300%"
              >
                <feDropShadow
                  dx="0"
                  dy="14"
                  stdDeviation="12"
                  floodColor="#000000"
                  floodOpacity=".92"
                />
              </filter>

              <clipPath id="rxFClip">
                <path d="
                  M78 270
                  L78 98
                  Q78 53 119 53
                  L273 53
                  L244 94
                  L128 94
                  L128 129
                  L234 129
                  L207 169
                  L128 169
                  L128 224
                  L101 272
                  Z
                " />
              </clipPath>
            </defs>

            {/* GOLD CONSTRUCTION TRAILS */}
            <g
              className="rx-gold-trails"
              fill="none"
              stroke="url(#rxGold)"
              strokeLinecap="round"
              strokeLinejoin="round"
              filter="url(#rxGoldGlow)"
            >
              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="4.2"
                d="
                  M95 272
                  C70 226 73 182 105 151
                  C128 129 124 96 128 72
                  C132 55 155 52 178 53
                  L254 53
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="3"
                d="
                  M73 92
                  C81 49 113 39 160 44
                  C215 48 255 49 276 48
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="3.3"
                d="
                  M91 260
                  C126 222 130 189 126 157
                  C123 140 141 129 169 129
                  C197 129 221 128 247 127
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="3"
                d="
                  M61 211
                  C89 189 112 171 154 162
                  C207 150 253 133 273 97
                  C289 67 270 45 240 47
                  C197 51 160 93 130 126
                  C96 164 72 205 69 246
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="3.6"
                d="
                  M54 84
                  C89 125 111 150 146 177
                  C184 206 223 230 246 232
                  C275 235 282 212 273 187
                  C257 145 210 105 169 77
                  C124 46 83 43 60 63
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="2.6"
                d="
                  M47 71
                  C96 109 123 122 173 151
                  C218 176 255 200 268 231
                  C280 261 258 278 231 268
                  C190 253 154 205 127 174
                  C95 138 63 112 50 104
                "
              />

              <path
                className="rx-trail"
                pathLength="1100"
                strokeWidth="2.8"
                d="
                  M91 276
                  C58 263 45 239 55 215
                  C70 177 119 162 155 149
                  C207 131 240 111 271 80
                "
              />
            </g>

            {/* DIM METAL SHAPE UNDER THE TRAILS */}
            <g className="rx-logo-outline">
              <path
                d="
                  M78 270
                  L78 98
                  Q78 53 119 53
                  L273 53
                  L244 94
                  L128 94
                  L128 129
                  L234 129
                  L207 169
                  L128 169
                  L128 224
                  L101 272
                  Z
                "
                fill="rgba(255,255,255,.1)"
              />
            </g>

            {/* FINAL 3D SILVER F */}
            <g
              className="rx-logo-metal"
              filter="url(#rxMetalShadow)"
            >
              <path
                d="
                  M78 270
                  L78 98
                  Q78 53 119 53
                  L273 53
                  L244 94
                  L128 94
                  L128 129
                  L234 129
                  L207 169
                  L128 169
                  L128 224
                  L101 272
                  Z
                "
                fill="url(#rxSilverFront)"
              />

              {/* dark left/lower extrusion */}
              <path
                d="
                  M78 98
                  L100 119
                  L100 246
                  L78 270
                  Z
                "
                fill="url(#rxSilverSide)"
                opacity=".95"
              />

              {/* top bevel */}
              <path
                d="
                  M119 53
                  L273 53
                  L258 74
                  L126 74
                  Q110 74 100 83
                  Q107 53 119 53
                  Z
                "
                fill="#ffffff"
                opacity=".72"
              />

              {/* top bar dark side */}
              <path
                d="
                  M128 94
                  L244 94
                  L228 112
                  L128 112
                  Z
                "
                fill="url(#rxSilverDark)"
                opacity=".9"
              />

              {/* middle bevel */}
              <path
                d="
                  M128 129
                  L234 129
                  L221 147
                  L128 147
                  Z
                "
                fill="#f7f7f7"
                opacity=".62"
              />

              {/* middle underside */}
              <path
                d="
                  M128 169
                  L207 169
                  L191 188
                  L128 188
                  Z
                "
                fill="url(#rxSilverDark)"
                opacity=".95"
              />

              {/* tiny warm lower edge visible in the reference */}
              <path
                d="
                  M78 224
                  L101 246
                  L101 272
                  L78 270
                  Z
                "
                fill="url(#rxGold)"
                opacity=".32"
              />

              {/* moving glint */}
              <g clipPath="url(#rxFClip)">
                <rect
                  className="rx-metal-glint"
                  x="-170"
                  y="10"
                  width="55"
                  height="330"
                  fill="rgba(255,255,255,.85)"
                  transform="skewX(-16)"
                />
              </g>
            </g>
          </svg>
        </div>

        <div className="rx-floor-light" />

        <div className="rx-brand-lockup">
          <div className="rx-word" aria-label="FALDREN">
            {"FALDREN".split("").map((letter, index) => (
              <span key={`${letter}-${index}`}>
                {letter}
              </span>
            ))}
          </div>
        </div>
      </div>

      <div className="rx-vignette" />
    </div>
  );
}

export default HomeLoader;
